import sympy
from sympy import Matrix, zeros, eye, Poly, re, im, expand_complex, rem, S
from sympy.abc import x, y
import itertools

# Standard algebra objects relevant to FieldTheory / Rings
I2 = eye(2)
I3 = eye(3)
O2 = zeros(2, 2)
O3 = zeros(3, 3)

def conditions(witness):
    """
    Checks if the witness is a valid counterexample to the false conjecture:
    "The kernel of the evaluation homomorphism is the principal ideal generated by the minimal polynomial."
    """
    if not isinstance(witness, dict):
        return [False, False, False]
        
    try:
        # Branch 1: Counterexample over the ring Z[2i]
        if witness.get('F') == 'Z[2i]':
            alpha = witness['alpha']
            m_poly = witness['m_poly']
            c_poly = witness['c_poly']
            
            m_expr = m_poly.as_expr() if hasattr(m_poly, 'as_expr') else m_poly
            m_p = Poly(m_expr, x)
            h1 = (m_expr.subs(x, alpha).simplify() == 0) and not m_p.is_zero
            
            c_expr = c_poly.as_expr() if hasattr(c_poly, 'as_expr') else c_poly
            c_p = Poly(c_expr, x)
            h2 = (c_expr.subs(x, alpha).simplify() == 0)
            
            def in_Z2i(c):
                c_exp = expand_complex(c)
                r_val = re(c_exp)
                i_val = im(c_exp)
                try:
                    return (S(r_val).is_integer == True) and (S(i_val).is_integer == True) and (S(i_val) % 2 == 0)
                except Exception:
                    return False
                    
            m_coeffs_ok = all(in_Z2i(c) for c in m_p.all_coeffs())
            c_coeffs_ok = all(in_Z2i(c) for c in c_p.all_coeffs())
            
            is_monic = (m_p.LC() == 1)
            is_minimal = (not in_Z2i(alpha)) if m_p.degree() == 2 else False
            
            r = rem(c_expr, m_expr, x)
            not_generated = not r.simplify().is_zero
            
            neg_q = m_coeffs_ok and c_coeffs_ok and is_monic and is_minimal and not_generated and h2
            
            return [bool(h1), bool(h2), bool(neg_q)]
            
        # Branch 2: Counterexample over a finite ring Z_n using matrices
        elif 'n' in witness:
            n = witness['n']
            alpha = witness['alpha']
            m_poly = witness['m_poly']
            c_poly = witness['c_poly']
            
            if not isinstance(n, int) or n < 2:
                return [False, False, False]
                
            k = alpha.shape[0]
            if alpha.shape != (k, k):
                return [False, False, False]
                
            m_expr = m_poly.as_expr() if hasattr(m_poly, 'as_expr') else m_poly
            m_p = Poly(m_expr, x)
            m_coeffs = m_p.all_coeffs()
            
            m_val = zeros(k, k)
            for i, c in enumerate(reversed(m_coeffs)):
                m_val += c * (alpha ** i)
            m_val = m_val.applyfunc(lambda val: val % n)
            
            h1 = m_val.is_zero_matrix and not m_p.is_zero
            
            c_expr = c_poly.as_expr() if hasattr(c_poly, 'as_expr') else c_poly
            c_p = Poly(c_expr, x)
            c_coeffs = c_p.all_coeffs()
            
            c_val = zeros(k, k)
            for i, c in enumerate(reversed(c_coeffs)):
                c_val += c * (alpha ** i)
            c_val = c_val.applyfunc(lambda val: val % n)
            
            h2 = c_val.is_zero_matrix
            
            is_monic = (m_p.LC() % n == 1)
            
            deg = m_p.degree()
            is_minimal = True
            if deg > 0:
                if deg > 3:
                    is_minimal = False
                else:
                    for d in range(deg):
                        found_zero = False
                        for coeffs in itertools.product(range(n), repeat=d):
                            val = (alpha ** d)
                            for i, c in enumerate(reversed(coeffs)):
                                val += c * (alpha ** i)
                            val = val.applyfunc(lambda v: v % n)
                            if val.is_zero_matrix:
                                found_zero = True
                                break
                        if found_zero:
                            is_minimal = False
                            break
                            
            def poly_div_mod(A, B, mod_n):
                A = [c % mod_n for c in A]
                B = [c % mod_n for c in B]
                while len(A) >= len(B) and len(A) > 0:
                    if A[0] == 0:
                        A.pop(0)
                        continue
                    factor = A[0]
                    for i in range(len(B)):
                        A[i] = (A[i] - factor * B[i]) % mod_n
                    A.pop(0)
                return any(c % mod_n != 0 for c in A)
                
            not_generated = poly_div_mod(c_coeffs, m_coeffs, n)
            
            neg_q = is_monic and is_minimal and not_generated and h2
            
            return [bool(h1), bool(h2), bool(neg_q)]
            
        else:
            return [False, False, False]
            
    except Exception:
        return [False, False, False]

CONDITION_LABELS = [
    "H_1: alpha is an element algebraic over F",
    "H_2: phi is the evaluation homomorphism defined by phi(g(x)) = g(alpha)",
    "¬Q: The kernel of phi is not the principal ideal generated by the minimal polynomial m(x)"
]

N_HYP = 2
NEG_Q_INDEX = 2